{
  "narratives": [
    {
      "item_code": "S7_HANDLING",
      "title_raw": "가. 안전취급요령",
      "start": "p4:L5",
      "end": "p4:L15"
    },
    {
      "item_code": "S7_STORAGE",
      "title_raw": "나. 안전한 저장 방법",
      "start": "p4:L16",
      "end": "p4:L24"
    }
  ]
  ,
  "extras": [
    {
      "after_item": "S7_HANDLING",
      "title_raw": "가. 안전취급요령",
      "reason": "코드없음",
      "statements": [
        {
          "value": "보관 온도가 높거나 3개월 이상 보관 후 사용 시 잘 섞어서 활성분 함량을 확인하고 사용하시오."
        ,
        "line": "p4:L6"
        },
        {
          "value": "동절기에 제품이 얼게되면 균일하게 용해 후 사용하시오."
        ,
        "line": "p4:L7"
        },
        {
          "value": "용해 시 포장제(드럼 등) 뚜껑을 열지 않도록 하시오."
        ,
        "line": "p4:L8"
        },
        {
          "value": "용해 시 온도는 50℃ 미만으로 하고, 50℃ 기준 48 시간을 넘기지 않도록 하시오."
        ,
        "line": "p4:L9"
        },
        {
          "value": "용해 시 열원(스팀 등)이 직접 포장제 및 제품에 가해지지 않도록 주의 하시오."
        ,
        "line": "p4:L10"
        },
        {
          "value": "공학적 관리 및 개인보호구를 참조하여 작업하시오."
        ,
        "line": "p4:L11"
        },
        {
          "value": "모든 안전 주의를 읽고 이해하기 전에는 취급하지 마시오."
        ,
        "line": "p4:L12"
        },
        {
          "value": "사용 전에 사용설명서를 입수하시오."
        ,
        "line": "p4:L13"
        },
        {
          "value": "용기가 비워진 후에도 제품 찌꺼기(증기, 액체, 고체)가 남아 있을 수 있으므로 모든 MSDS, 라벨 예방조치를 따르시오."
        ,
        "line": "p4:L14"
        },
        {
          "value": "장기간 또는 반복적으로 증기를 흡입하지 마시오."
        ,
        "line": "p4:L15"
        }
      ]
    ,
    "suggested_code": "S7_HANDLING"
    ,
    "line": "p4:L5"
    },
    {
      "after_item": "S7_STORAGE",
      "title_raw": "나. 안전한 저장 방법",
      "reason": "코드없음",
      "statements": [
        {
          "value": "현행 법규 및 규정에 의하여 저장 및 취급 할 것."
        ,
        "line": "p4:L17"
        },
        {
          "value": "누출여부를 주기적으로 점검하시오."
        ,
        "line": "p4:L18"
        },
        {
          "value": "사용하지 않을 시에는 밀폐하여 놓으시오."
        ,
        "line": "p4:L19"
        },
        {
          "value": "서늘하고 건조하며 통풍이 잘 되는 장소에 저장하시오."
        ,
        "line": "p4:L20"
        },
        {
          "value": "적정 보관 온도는 15~30℃ 이며, 보관장소의 온도 변화를 최소화 하시오."
        ,
        "line": "p4:L21"
        },
        {
          "value": "혼합 금지 물질과 분리 할 것."
        ,
        "line": "p4:L22"
        },
        {
          "value": "손상된 용기는 사용하지 마시오."
        ,
        "line": "p4:L23"
        },
        {
          "value": "용기에 물리적인 충격을 가하지 마시오."
        ,
        "line": "p4:L24"
        }
      ]
    ,
    "suggested_code": "S7_STORAGE"
    ,
    "line": "p4:L16"
    }
  ]
}

